void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
  if (new_len < 0) {
    return;
  }

  if (new_len > PANGO_MAX_GLYPHS) {
    g_error("Glyph string length exceeds maximum allowed limit");
  }

  if (string->glyphs == NULL) {
    string->glyphs = g_malloc(new_len * sizeof(PangoGlyph));
    string->log_clusters = g_malloc(new_len * sizeof(gint));
  } else {
    gint allocated_len = MAX(new_len, PANGO_GLYPH_STRING_ALLOC(string));
    string->glyphs = g_realloc(string->glyphs, allocated_len * sizeof(PangoGlyph));
    string->log_clusters = g_realloc(string->log_clusters, allocated_len * sizeof(gint));
  }

  string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint limit = G_MAXINT / sizeof(PangoGlyph);
    gint new_size;

    g_return_if_fail(new_len >= 0);

    if (string->num_glyphs == new_len)
        return;

    if (new_len > string->allocated_len) {
        new_size = MAX(new_len, string->allocated_len * 2);
        if (new_size > limit)
            new_size = limit;

        string->glyphs = g_renew(PangoGlyph, string->glyphs, new_size);
        string->log_clusters = g_renew(gint, string->log_clusters, new_size);
        string->allocated_len = new_size;
    }

    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint max_size = G_MAXINT;
    gint len = string->num_glyphs;

    if (new_len < 0)
        g_return_if_reached();

    if (new_len > max_size)
        g_error("New length exceeds maximum size limit");

    if (new_len > string->allocated_len) {
        while (string->allocated_len < new_len)
            string->allocated_len = MAX(1, string->allocated_len * 2);
    }

    string->glyphs = g_renew(PangoGlyph, string->glyphs, string->allocated_len);
    string->log_clusters = g_renew(gint, string->log_clusters, string->allocated_len);

    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
    gint allocated;
    gint max_size = G_MAXINT / sizeof(PangoGlyph);

    g_return_if_fail(new_len >= 0);

    if (new_len == string->num_glyphs)
        return;

    allocated = string->allocated_len;

    while (allocated < new_len && allocated < max_size)
        allocated = MAX(allocated * 2, new_len);

    if (allocated > max_size) {
        g_error("Cannot allocate %d glyphs", new_len);
    }

    string->glyphs = g_renew(PangoGlyph, string->glyphs, allocated);
    string->log_clusters = g_renew(gint, string->log_clusters, allocated);
    string->allocated_len = allocated;
    string->num_glyphs = new_len;
}

void pango_glyph_string_set_size(PangoGlyphString *string, gint new_len) {
  gint max_size = G_MAXINT;
  gint len;

  g_return_if_fail(new_len >= 0);

  len = new_len;

  if (string->glyphs == NULL) {
    string->glyphs = g_malloc0(sizeof(PangoGlyph) * len);
    string->log_clusters = g_malloc0(sizeof(gint) * len);
  } else {
    gint allocated_len = MAX(string->num_glyphs, string->allocated_len);

    while (allocated_len < len) {
      allocated_len = MIN(allocated_len * 2, max_size);
    }

    string->glyphs = g_realloc(string->glyphs, sizeof(PangoGlyph) * allocated_len);
    string->log_clusters = g_realloc(string->log_clusters, sizeof(gint) * allocated_len);
  }

  string->num_glyphs = len;
}
